assert set(T) == set(live), (sorted(set(live) ^ set(T)))
import re
def acceptance(n):
    body = json.loads(subprocess.check_output(["gh", "issue", "view", str(n), "-R", R, "--json", "body"], text=True, encoding="utf8"))["body"]
    m = re.search(r"### Acceptance criteria\n(.*?)\n### ", body, re.S)
    return [l[6:].strip() for l in (m.group(1).splitlines() if m else []) if l.startswith("- [ ] ") or l.startswith("- [x] ")]
STRETCH = {128, 130, 131, 132, 133, 134, 135}
rows = []
for n in sorted(T):
    k, done, varun, auth, tests, closes, unlocks, whole = T[n]
    rows.append({"issue": n, "url": f"https://github.com/{R}/issues/{n}", "title": live[n]["title"], "currentAssignees": [a["login"] for a in live[n]["assignees"]], "kind": k, "claudeCompleted": done,
                 "varunTasks": varun, "authorisedActor": auth, "tests": tests, "closeWhen": closes, "unlocks": unlocks, "acceptanceCriteria": acceptance(n), "labels": [l["name"] for l in live[n]["labels"] if l["name"].startswith("owner:")], "stretchUnfinished": n in STRETCH,
                 "stretchNote": ("UNFINISHED STRETCH WORK. Only disabled rule modules exist in packages/stretch (no UI, no data, not released). Hard-depends on #126; do not describe as a completed feature." if n in STRETCH else ""), "assignmentNote": "transferred to varunkarthic on 2026-11-08; Claude had recommended keeping this issue with Developer B while independent UI work remained" if not whole else "transferred to varunkarthic on 2026-11-08"})
json.dump({"status": "TRANSFER COMPLETED on GitHub (all 26 open issues assigned to varunkarthic, 2026-11-08). owner:developer-b labels and closed history unchanged.", "assignee": "varunkarthic", "issues": rows}, open("docs/project/future-varun-responsibilities.json", "w", encoding="utf8"), indent=1, ensure_ascii=False)
md = ["# Varun responsibilities (transfer completed)", "", "**Status:** all 26 open Developer B issues are assigned to `varunkarthic` on GitHub (verified live when this file was generated; the change was made on 2026-11-08 by account actions, not by Claude). The `owner:developer-b` workstream label and all historical contributions are unchanged. Varun **coordinates** human, device and external work; he cannot issue approvals that must come from the named authority. Generated by `python docs/project/make_varun_transfer.py`; data in `future-varun-responsibilities.json`.", ""]
for r in rows:
    md += [f"## #{r['issue']} {r['title']}", f"- Link: {r['url']}; current assignee: {', '.join(r['currentAssignees']) or 'none'}; kind: {r['kind']}",
           f"- Claude completed: {r['claudeCompleted']}", f"- Varun does: {r['varunTasks']}", f"- Authorised actor: {r['authorisedActor']}", f"- Tests / commands: {r['tests']}",
           f"- Close when: {r['closeWhen']}", f"- Unlocks: {r['unlocks']}", f"- Acceptance criteria (unchanged, from the issue): " + ("; ".join(r["acceptanceCriteria"]) or "see issue"), f"- Labels: {', '.join(r['labels'])}", f"- Note: {r['assignmentNote']}"] + ([f"- **{r['stretchNote']}**"] if r["stretchUnfinished"] else []) + [""]
open("docs/project/FUTURE_VARUN_RESPONSIBILITIES.md", "w", encoding="utf8").write("\n".join(md))
print(len(rows), sum(r["stretchUnfinished"] for r in rows), sorted({a for r in rows for a in r["currentAssignees"]}))
